# ================================================================ OA 10 clase 3
L(OA10, 3,
  use="Aprenderé a interpretar la pendiente y el intercepto de una función afín. Sirve para explicar qué significa cada número en una situación real.",
  prior=["Sé escribir la regla desde una tabla.", "Sé calcular cambios entre dos puntos."],
  explain=[
      "En y = ax + b, el número a se llama pendiente: dice cuánto cambia y cuando x sube 1. Si a es positivo, la recta sube; si es negativo, baja; si es 0, es horizontal. El número b se llama intercepto con el eje y: es el valor de y cuando x vale 0, el punto (0, b).",
      "Con dos puntos de la recta (x₁, y₁) y (x₂, y₂) se calcula la pendiente dividiendo el cambio de y por el cambio de x: a = (y₂ − y₁)/(x₂ − x₁). Si pasa por (1, 5) y (3, 9), a = (9 − 5)/(3 − 1) = 4/2 = 2. Luego b = y₁ − a · x₁ = 5 − 2 = 3, entonces y = 2x + 3.",
      "En un problema, a es el cambio por unidad y b es el valor inicial. En y = 500x + 1.000, un servicio cobra 500 por cada unidad y 1.000 fijos. En y = −2x + 10, algo baja 2 por cada unidad y parte en 10, así que llega a 0 cuando x = 5.",
  ],
  vocab=[("pendiente", "cambio de y por cada 1 que sube x (el número a)"), ("intercepto", "valor de y cuando x vale 0 (el número b)"), ("creciente", "función cuyo y aumenta al aumentar x"), ("decreciente", "función cuyo y disminuye al aumentar x"), ("cambio constante", "pendiente de una función afín")],
  worked=[
      ("Pendiente desde dos puntos", "Una recta pasa por (1, 5) y (3, 9). Calcula la pendiente y el intercepto.", ["Pendiente: (9 − 5)/(3 − 1) = 4/2 = 2.", "Intercepto: b = 5 − 2 · 1 = 3. La regla es y = 2x + 3."], "a = 2 y b = 3"),
      ("Interpretar", "Un servicio cobra y = 500x + 1.000 pesos por x unidades. ¿Qué significan 500 y 1.000?", ["500 es lo que cambia el cobro por cada unidad.", "1.000 es el cobro fijo cuando no se usa ninguna unidad."], "500: precio por unidad; 1.000: cobro fijo"),
  ],
  mist=[
      ("Calcular la pendiente de (1, 5) y (3, 9) como (3 − 1)/(9 − 5).", "Se invirtió el cociente.", "Se divide el cambio de y por el cambio de x: 4/2 = 2."),
      ("Decir que en y = −2x + 10 el intercepto es −2.", "Se confundió la pendiente con el intercepto.", "El intercepto es 10; −2 es la pendiente."),
  ],
  R=[ex("En y = 3x + 5, ¿cuánto valen la pendiente y el intercepto?", "Pendiente 3 e intercepto 5", "a es el número que multiplica a x y b el que se suma."),
     cx("Una recta pasa por (0, 2) y (1, 6). ¿Cuál es su pendiente?", "F(6-2,1-0)", "El cambio de y es 4 y el cambio de x es 1."),
     ex("En y = 500x + 1.000, ¿qué indica el 1.000?", "El cobro fijo", "Es el valor cuando x = 0.")],
  C=[cx("Una recta pasa por (2, 3) y (5, 12). ¿Cuál es su pendiente?", "F(12-3,5-2)", "El cambio de y es 9 en 3 pasos de x."),
     cx("En y = −2x + 10, ¿para qué valor de x se tiene y = 0?", "sol(-2,10,0,0)", "−2x + 10 = 0 da x = 5."),
     ex("¿Cuál es el intercepto con el eje y de la recta y = 4x − 6?", "−6", "Es el valor de y cuando x = 0.")],
  A=[ex("Un taxi de ejemplo cobra y = 700x + 1.200 pesos por x km. ¿Cuánto cuesta cada kilómetro y cuánto la bajada?", "700 pesos por km y 1.200 de bajada", "La pendiente es el precio por km y el intercepto es la bajada."),
     cx("Un depósito de ejemplo tiene 60 litros y pierde 4 litros por minuto: y = −4x + 60. ¿En cuántos minutos queda vacío?", "sol(-4,60,0,0)", "−4x + 60 = 0 da x = 15.", unit=" minutos"),
     cx("Una recta pasa por (2, 7) y (6, 19). ¿Cuál es su pendiente?", "F(19-7,6-2)", "El cambio de y es 12 en 4 pasos de x.")],
  Z=[ex("Carla dice que en y = −2x + 10 el intercepto es −2. Corrígela.", "El intercepto es 10", "−2 es la pendiente y el intercepto es el término sin x."),
     ex("¿Tienen la misma pendiente y = 2x + 1 e y = 2x + 7? Responde Sí o No.", "Sí", "En las dos la pendiente es 2.")],
  D=[cx("Una recta pasa por (−1, 4) y (3, −4). ¿Cuál es su pendiente?", "F(-4-4,3-(-1))", "El cambio de y es −8 en 4 pasos de x."),
     cx("Una recta tiene pendiente 3 y pasa por (2, 5). ¿Cuál es su intercepto?", "5-3*2", "b = y − a · x = 5 − 6.")],
  ctx=[ex("Una piscina de ejemplo tiene 200 litros y se llena a 30 litros por minuto: y = 30x + 200. ¿Qué significan el 30 y el 200?", "30: litros que entran por minuto; 200: litros iniciales", "La pendiente es la rapidez de llenado y el intercepto, el contenido inicial.")],
  chk=[ex("¿La recta y = −3x + 8 sube o baja al aumentar x?", "Baja", "La pendiente es negativa."),
       cx("Una recta pasa por (0, 1) y (2, 7). ¿Cuál es su pendiente?", "F(7-1,2-0)", "El cambio de y es 6 en 2 pasos de x."),
       ex("En y = 6x + 9, ¿cuál es el intercepto?", "9", "Es el término sin x.")],
  op=("Dos puntos de ejemplo de una recta son (2, 8) y (5, 17), que representan el costo en pesos (y, en miles) de x horas de un servicio. Calcula la pendiente, el intercepto y la regla. Escribe una frase que explique qué significa cada uno en esta situación y calcula el costo de 10 horas.",
      "Pendiente: (17 − 8)/(5 − 2) = 3 mil por hora. Intercepto: 8 − 3 · 2 = 2 mil de costo fijo. Regla: y = 3x + 2. Para 10 horas: 32 mil pesos.",
      ["calcula pendiente e intercepto", "escribe la regla", "interpreta cada número en el contexto"],
      ["cálculos", "regla", "frase de interpretación"],
      ["invertir el cociente de la pendiente", "confundir pendiente con intercepto"],
      "Pide que compruebe la regla con los dos puntos dados."),
  reinforce="Calcula la pendiente de la recta que pasa por (1, 3) y (4, 12) y escribe su regla.",
  extend="Explica qué ocurre con la recta cuando la pendiente es 0 y da un ejemplo de situación.",
)

