  A=[cx("Plan A: 6.000 pesos fijos más 400 por hora. Plan B: 2.000 pesos fijos más 900 por hora. ¿Con cuántas horas cuestan lo mismo?", "sol(400,6000,900,2000)", "Se igualan las reglas y 500x = 4.000.", unit=" horas"),
     cx("Con el mismo plan A y B, ¿cuánto cuesta el plan A con 4 horas?", "400*4+6000", "Se multiplica y se suma lo fijo.", unit=" pesos"),
     cx("Una persona de ejemplo ahorra con interés simple 500.000 pesos al 2 % anual. ¿Cuánto tiene a los 5 años?", "500000+500000*F(2,100)*5", "El interés anual es 10.000 y en 5 años gana 50.000.", unit=" pesos")],
  Z=[ex("Rosa calculó el interés simple del año 2 sobre el valor del año 1. ¿Qué tipo de interés calculó?", "Compuesto", "En el simple, cada año gana lo mismo sobre el capital inicial."),
     ex("Un modelo dice que un servicio cuesta y = 800x + 3.000 con x kilómetros. ¿Tiene sentido x = −2? Responde Sí o No.", "No", "Una distancia no puede ser negativa.")],
  D=[cx("Plan A: 2.000 pesos fijos más 400 por hora. Plan B: 600 por hora sin cobro fijo. ¿Con cuántas horas cuestan lo mismo?", "sol(400,2000,600,0)", "400x + 2.000 = 600x da 200x = 2.000.", unit=" horas"),
     cx("Un ahorro con interés simple de 3 % anual llega a 112.000 pesos en 4 años. ¿Cuál era el capital inicial?", "sol(F(112,100),0,0,112000)", "El capital crece 12 % en 4 años: C · 1,12 = 112.000.", unit=" pesos")],
  ctx=[cx("Un ahorro de ejemplo de 400.000 pesos gana 2 % de interés simple al año. ¿Cuánto interés gana cada año?", "400000*F(2,100)", "2 % de 400.000.", unit=" pesos")],
