  vocab=[("red", "dibujo de las caras de un cuerpo desplegadas en un plano"), ("base", "cara en que apoya el prisma o el cilindro"), ("cara lateral", "cara que une las dos bases"), ("circunferencia", "largo del borde del círculo: 2π · r"), ("π (pi)", "número aproximado a 3,14 que relaciona la circunferencia con el diámetro")],
